public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    for (int i = 0; i < str.length(); i++) {
        // Get the current character from the string
        char c = str.charAt(i);

        // Check if the character is in the basic ASCII range (i.e., it has a code point <= 0x7F)
        if (c <= 0x7F) {
            // If so, it's a 7-bit ASCII character and can be written directly
            lb.writeByte((byte) c);
        } else {
            // If not, it's a multi-byte character and needs to be written in UTF-8
            lb.writeByte((byte) (0xE0 | (c >> 12)));
            lb.writeByte((byte) (0x80 | ((c >> 6) & 0x3F)));
            lb.writeByte((byte) (0x80 | (c & 0x3F)));
        }
    }

    return lb;
}

