    Node current = start;
    OuterFaceCirculator circulator = new OuterFaceCirculator(current, dir);

    // Iterate over the nodes on the outer face of the component
    while (circulator.hasNext()) {
        Node node = circulator.next();

        // Check if the node satisfies the predicate
        if (predicate.test(node)) {
            return circulator;
        }

        // Check if the node is the stop node
        if (node == stop) {
            break;
        }
    }

    // If no node satisfying the predicate was found, return the circulator to the stop node
    return new OuterFaceCirculator(stop, dir);
}

