  * This method checks the consistency of the sharding key indices in the specified model.
  * @param model Name of the model to be checked.
  * @throws IllegalStateException If the sharding key indices are not continuous.
  */
public void check(String modelName) throws IllegalStateException {
    // Initialization
    Map<String, Integer> shardingKeyIndices = new HashMap<>();

    // Find the sharding key indices for the specified model
    for (Field field : getDBSchema().getModel(modelName).getFields()) {
        if (field.getFacets().contains(Facet.SHARDING_KEY)) {
            shardingKeyIndices.put(field.getName(), field.getIndex());
        }
    }

    // Check if the sharding key indices are continuous
    for (int i = 0; i < shardingKeyIndices.size(); i++) {
        if (i != shardingKeyIndices.get(shardingKeyIndices.keySet().toArray()[i])) {
            throw new IllegalStateException("Sharding key indices are not continuous in model " + modelName);
        }
    }
}

